-- ===== is_active_member_mfa() / is_active_member() directly =====
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"e1000000-0000-4000-8000-0000000000a2","aal":"aal2","role":"authenticated"}', true);
select is(public.is_active_member_mfa(array['admin']), true, 'mfa fn: active admin at aal2 -> true');
select is(public.is_active_member_mfa(array['owner']), false, 'mfa fn: role not in list -> false');
select is(public.is_active_member_mfa(array[]::text[]), false, 'mfa fn: empty role list -> false');
select is(public.is_active_member_mfa(null), false, 'mfa fn: null role list -> false (fail closed)');
select set_config('request.jwt.claims', '{"sub":"e1000000-0000-4000-8000-0000000000a2","aal":"aal1","role":"authenticated"}', true);
select is(public.is_active_member_mfa(array['admin']), false, 'mfa fn: active admin at aal1 -> false');
select is(public.is_active_member(array['admin']), true, 'role probe: is_active_member stays true at aal1 (UI probe, no data access)');
select set_config('request.jwt.claims', '{"sub":"e1000000-0000-4000-8000-0000000000a2","role":"authenticated"}', true);
select is(public.is_active_member_mfa(array['admin']), false, 'mfa fn: missing aal claim -> false');
select set_config('request.jwt.claims', '{"sub":"e1000000-0000-4000-8000-0000000000a2","aal":["aal2"],"role":"authenticated"}', true);
select is(public.is_active_member_mfa(array['admin']), false, 'mfa fn: non-string aal claim (array) -> false');
select set_config('request.jwt.claims', '{"sub":"e1000000-0000-4000-8000-0000000000a5","aal":"aal2","role":"authenticated"}', true);
select is(public.is_active_member_mfa(array['owner', 'admin', 'analyst']), false, 'mfa fn: nonmember at aal2 -> false');
select set_config('request.jwt.claims', '{"aal":"aal2","role":"authenticated"}', true);
select is(public.is_active_member_mfa(array['owner', 'admin', 'analyst']), false, 'mfa fn: aal2 but no sub -> false');
reset role;
set local role anon;
select set_config('request.jwt.claims', '{"role":"anon","aal":"aal2"}', true);
select throws_ok($q$select public.is_active_member_mfa(array['owner'])$q$, '42501', null, 'anon: is_active_member_mfa EXECUTE denied');
reset role;
set local role service_role;
select set_config('request.jwt.claims', '{"role":"service_role"}', true);
select throws_ok($q$select public.is_active_member_mfa(array['owner'])$q$, '42501', null, 'service_role: is_active_member_mfa EXECUTE denied');
select throws_ok($q$select * from public.job_status_summary()$q$, '42501', null, 'service_role (L6): job_status_summary EXECUTE denied');
select throws_ok($q$select * from public.usage_daily_summary(current_date - 1, current_date)$q$, '42501', null, 'service_role (L6): usage_daily_summary EXECUTE denied');
select throws_ok($q$select * from public.knowledge_gaps(current_date - 1, current_date, 10)$q$, '42501', null, 'service_role (L6): knowledge_gaps EXECUTE denied');
